#!/usr/bin/env python3
from pathlib import Path
import base64
ROOT=Path.cwd()
def read(path):
    p=ROOT/path
    if not p.exists(): raise SystemExit(f"Fichier introuvable : {path}")
    return p.read_text(encoding="utf-8")
def write(path,content):
    p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding="utf-8")
write("public/admin-media.js",base64.b64decode('').decode())
write("public/admin-media.css",base64.b64decode('').decode())
path="src/pages/admin/index.astro"
content=read(path)
if '/admin-media.css' not in content:
    content=content.replace('    <link rel="stylesheet" href="/admin-staging.css">','    <link rel="stylesheet" href="/admin-staging.css">\n    <link rel="stylesheet" href="/admin-media.css?v=1">')
if '/admin-media.js' not in content:
    content=content.replace('    <script is:inline src="/admin-team-staff.js"></script>','    <script is:inline src="/admin-media.js?v=1"></script>\n    <script is:inline src="/admin-team-staff.js"></script>')
write(path,content)
print("Cropper installé : public/admin-media.js, public/admin-media.css, src/pages/admin/index.astro")
